set -e; if command -v apt-get >/dev/null 2>&1; then apt-get update -y || true; DEBIAN_FRONTEND=noninteractive apt-get install -y openssh-server || true; elif command -v dnf >/dev/null 2>&1; then dnf install -y openssh-server || true; elif command -v yum >/dev/null 2>&1; then yum install -y openssh-server || true; elif command -v pacman >/dev/null 2>&1; then pacman -Sy --noconfirm openssh || true; elif command -v zypper >/dev/null 2>&1; then zypper --non-interactive install openssh-server || true; elif command -v apk >/dev/null 2>&1; then apk add --no-cache openssh-server || true; fi; mkdir -p ~/.ssh && chmod 700 ~/.ssh; grep -Fqx {{public_key}} ~/.ssh/authorized_keys 2>/dev/null || echo {{public_key}} >> ~/.ssh/authorized_keys; chmod 600 ~/.ssh/authorized_keys; ssh-keygen -A; if [ "$(id -u)" = "0" ]; then mkdir -p /run/sshd; fi; chown "$(id -u):$(id -g)" ~ ~/.ssh ~/.ssh/authorized_keys 2>/dev/null || true; chmod 700 ~; {{start_script}}; echo "OK $(whoami)"
